cd /workspace
runuser -u dev -- ddev drush ev '
$profile = "openculturas";
$profiles = \Drupal::service("extension.list.profile")->getList();
$info = $profiles[$profile]->info;
$modules = $info["install"];
$files = \Drupal::service("extension.list.module")->getList();
$extra = [];
foreach ($modules as $m) { if (isset($files[$m]->requires)) { foreach (array_keys($files[$m]->requires) as $r) { $extra[$r]=1; } } }
$modules = array_diff(array_unique(array_merge($modules, array_keys($extra))), ["system"]);
ksort($modules);
$all = [];
foreach ($modules as $m) { $all[] = $m; }
echo "TOTAL: " . count($all) . "\n";
foreach ($all as $i => $m) { if (strpos($m, "geocoder") === 0 || strpos($m, "openstreetmap") !== false || $m == "geofield" || strpos($m,"openculturas") === 0) { echo "$i $m\n"; } }
' 2>&1 | head -30
